'use client';

import { useEffect, useRef, useState } from 'react';

import { MailIcon, UserRoundPlusIcon } from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';
import { Field, FieldLabel } from '@/registry/ndeko/ui/field';
import { Input } from '@/registry/ndeko/ui/input';

import {
  AuthFrame,
  CardHead,
  ErrorPresence,
  MarkTile,
  StepSwap,
  SubmitButton,
} from './auth-kit';
import {
  CREATE_DELAY_MS,
  EMAIL_PLACEHOLDER,
  LINK_LIFETIME_HOURS,
} from './data';
import {
  PasswordField,
  PasswordRules,
  areRulesMet,
  personalWordsOf,
  rulesOf,
} from './password-parts';

type Step = 'form' | 'confirm';

type SignUpField = 'name' | 'email' | 'password';

type SignUpErrors = Partial<Record<SignUpField, string>>;

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

const FIELD_ORDER: SignUpField[] = ['name', 'email', 'password'];

function emailProblemOf(email: string) {
  const trimmed = email.trim();
  if (trimmed.length === 0) {
    return 'Enter your work email';
  }
  const isValid = EMAIL_PATTERN.test(trimmed);
  if (!isValid) {
    return 'Enter an email like name@company.com';
  }
  return undefined;
}

function nameProblemOf(name: string) {
  const trimmed = name.trim();
  if (trimmed.length === 0) {
    return 'Enter your name as teammates will see it';
  }
  return undefined;
}

function passwordProblemOf(isPasswordReady: boolean) {
  if (isPasswordReady) {
    return undefined;
  }
  return 'Meet every rule below to continue';
}

function firstErrorFieldOf(errors: SignUpErrors) {
  const field = FIELD_ORDER.find((candidate) => Boolean(errors[candidate]));
  if (field) {
    return field;
  }
  return null;
}

function withoutError(errors: SignUpErrors, field: SignUpField) {
  if (!errors[field]) {
    return errors;
  }
  const next = { ...errors };
  delete next[field];
  return next;
}

function errorOf(errors: SignUpErrors, field: SignUpField) {
  return errors[field] ?? null;
}

export default function Auth02() {
  const [step, setStep] = useState<Step>('form');
  const [hasMoved, setHasMoved] = useState(false);
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [errors, setErrors] = useState<SignUpErrors>({});
  const [isCreating, setIsCreating] = useState(false);
  const nameRef = useRef<HTMLInputElement>(null);
  const emailRef = useRef<HTMLInputElement>(null);
  const passwordRef = useRef<HTMLInputElement>(null);
  const personalWords = personalWordsOf(name, email);
  const rules = rulesOf(password, personalWords);
  const isPasswordReady = areRulesMet(rules);
  const trimmedEmail = email.trim();
  const nameError = errorOf(errors, 'name');
  const emailError = errorOf(errors, 'email');
  const passwordError = errorOf(errors, 'password');
  const hasNameError = Boolean(nameError);
  const hasEmailError = Boolean(emailError);

  useEffect(() => {
    if (!isCreating) {
      return;
    }
    const timer = window.setTimeout(() => {
      setIsCreating(false);
      setPassword('');
      setStep('confirm');
      setHasMoved(true);
    }, CREATE_DELAY_MS);
    return () => window.clearTimeout(timer);
  }, [isCreating]);

  function clearError(field: SignUpField) {
    setErrors((previous) => withoutError(previous, field));
  }

  function changeName(event: React.ChangeEvent<HTMLInputElement>) {
    setName(event.target.value);
    clearError('name');
  }

  function changeEmail(event: React.ChangeEvent<HTMLInputElement>) {
    setEmail(event.target.value);
    clearError('email');
  }

  function changePassword(value: string) {
    setPassword(value);
    clearError('password');
  }

  function focusField(field: SignUpField) {
    const refs = { name: nameRef, email: emailRef, password: passwordRef };
    refs[field].current?.focus();
  }

  function submit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (isCreating) {
      return;
    }
    const nextErrors: SignUpErrors = {
      name: nameProblemOf(name),
      email: emailProblemOf(email),
      password: passwordProblemOf(isPasswordReady),
    };
    const firstField = firstErrorFieldOf(nextErrors);
    setErrors(nextErrors);
    if (firstField) {
      focusField(firstField);
      return;
    }
    setIsCreating(true);
  }

  function switchEmail() {
    setStep('form');
    setHasMoved(true);
  }

  return (
    <AuthFrame footer='By creating an account you accept the terms of service and the privacy notice'>
      <StepSwap stepKey={step}>
        {step === 'form' && (
          <>
            <CardHead
              mark={<MarkTile icon={UserRoundPlusIcon} />}
              title='Create your Tidewell account'
            >
              Start a workspace for your team. You can invite people once it is
              ready.
            </CardHead>
            <form noValidate onSubmit={submit} className='flex flex-col gap-5'>
              <Field invalid={hasNameError} className='gap-0'>
                <FieldLabel className='mb-1.5'>Full name</FieldLabel>
                <Input
                  ref={nameRef}
                  autoComplete='name'
                  placeholder='Amara Okafor'
                  value={name}
                  readOnly={isCreating}
                  autoFocus={hasMoved}
                  onChange={changeName}
                />
                <ErrorPresence error={nameError} />
              </Field>
              <Field invalid={hasEmailError} className='gap-0'>
                <FieldLabel className='mb-1.5'>Work email</FieldLabel>
                <Input
                  ref={emailRef}
                  type='email'
                  inputMode='email'
                  autoComplete='email'
                  placeholder={EMAIL_PLACEHOLDER}
                  value={email}
                  readOnly={isCreating}
                  onChange={changeEmail}
                />
                <ErrorPresence error={emailError} />
              </Field>
              <PasswordField
                label='Password'
                value={password}
                autoComplete='new-password'
                error={passwordError}
                inputRef={passwordRef}
                readOnly={isCreating}
                onValueChange={changePassword}
              >
                <PasswordRules rules={rules} />
              </PasswordField>
              <SubmitButton
                label='Create account'
                workingLabel='Creating account'
                isWorking={isCreating}
              />
            </form>
          </>
        )}
        {step === 'confirm' && (
          <>
            <CardHead
              mark={<MarkTile icon={MailIcon} />}
              title='Confirm your email'
              autoFocusTitle
            >
              We sent a link to{' '}
              <span className='text-foreground font-medium break-all'>
                {trimmedEmail}
              </span>
              {`. Open it within ${LINK_LIFETIME_HOURS} hours to finish creating your account.`}
            </CardHead>
            <p className='bg-foreground/[0.03] text-muted-foreground rounded-lg px-3 py-2 text-xs'>
              This preview sends no email and keeps no password
            </p>
            <div className='flex justify-end'>
              <Button variant='outline' size='lg' onClick={switchEmail}>
                Use another email
              </Button>
            </div>
          </>
        )}
      </StepSwap>
    </AuthFrame>
  );
}

'use client';

import {
  AnimatePresence,
  motion,
  type Transition,
  type Variants,
} from 'motion/react';
import { useState } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import {
  CheckIcon,
  CircleIcon,
  EyeIcon,
  EyeOffIcon,
} from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';
import { Field, FieldDescription, FieldLabel } from '@/registry/ndeko/ui/field';
import { Input } from '@/registry/ndeko/ui/input';

import { ErrorPresence } from './auth-kit';

export const PASSWORD_MIN_LENGTH = 10;

const PERSONAL_WORD_MIN_LENGTH = 3;

const SWAP_TRANSITION: Transition = { duration: 0.15, ease: [0.2, 0, 0, 1] };

const SWAP_VARIANTS: Variants = {
  enter: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
  visible: { opacity: 1, scale: 1, filter: 'blur(0px)' },
  exit: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
};

const FADE_VARIANTS: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1 },
  exit: { opacity: 0 },
};

const UPPERCASE_PATTERN = /\p{Lu}/u;

const LOWERCASE_PATTERN = /\p{Ll}/u;

const DIGIT_PATTERN = /\d/;

export type PasswordRule = {
  id: string;
  label: string;
  isMet: boolean;
};

function swapVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return SWAP_VARIANTS;
}

function isTellingWord(word: string) {
  return word.length >= PERSONAL_WORD_MIN_LENGTH;
}

/** Words that would make the password easy to guess: parts of the name and of the email. */
export function personalWordsOf(name: string, email: string) {
  const loweredName = name.toLowerCase();
  const loweredEmail = email.toLowerCase();
  const [localPart] = loweredEmail.split('@');
  const nameParts = loweredName.split(/\s+/);
  const words = [...nameParts, localPart];
  return words.filter(isTellingWord);
}

export function rulesOf(
  password: string,
  personalWords: string[]
): PasswordRule[] {
  const lowered = password.toLowerCase();
  const hasPassword = password.length > 0;
  const isLongEnough = password.length >= PASSWORD_MIN_LENGTH;
  const hasDigit = DIGIT_PATTERN.test(password);
  const hasUppercase = UPPERCASE_PATTERN.test(password);
  const hasLowercase = LOWERCASE_PATTERN.test(password);
  const hasBothCases = hasUppercase && hasLowercase;
  const usesPersonalWord = personalWords.some((word) => lowered.includes(word));
  const isImpersonal = hasPassword && !usesPersonalWord;
  return [
    {
      id: 'length',
      label: `At least ${PASSWORD_MIN_LENGTH} characters`,
      isMet: isLongEnough,
    },
    { id: 'digit', label: 'One number', isMet: hasDigit },
    {
      id: 'cases',
      label: 'Upper and lower case letters',
      isMet: hasBothCases,
    },
    {
      id: 'personal',
      label: 'Not your name or email',
      isMet: isImpersonal,
    },
  ];
}

export function areRulesMet(rules: PasswordRule[]) {
  return rules.every((rule) => rule.isMet);
}

function metCountLabelOf(rules: PasswordRule[]) {
  const metCount = rules.filter((rule) => rule.isMet).length;
  return `${metCount} of ${rules.length} password rules met`;
}

function RuleMark({ isMet }: { isMet: boolean }) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const variants = swapVariantsOf(shouldReduceMotion);
  const markKey = String(isMet);

  return (
    <span aria-hidden='true' className='relative flex size-4 shrink-0'>
      <AnimatePresence mode='popLayout' initial={false}>
        <motion.span
          key={markKey}
          variants={variants}
          initial='enter'
          animate='visible'
          exit='exit'
          transition={SWAP_TRANSITION}
          className='flex size-4 items-center justify-center'
        >
          {isMet && (
            <span className='bg-success/15 text-success-foreground flex size-4 items-center justify-center rounded-full'>
              <CheckIcon strokeWidth={2.5} className='size-2.5' />
            </span>
          )}
          {!isMet && (
            <CircleIcon className='text-muted-foreground/60 size-3.5' />
          )}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

/** Rules tick one by one as the password meets them. Rendered inside the password `Field`. */
export function PasswordRules({ rules }: { rules: PasswordRule[] }) {
  const metCountLabel = metCountLabelOf(rules);

  return (
    <FieldDescription render={<div />} className='pt-2.5'>
      <ul className='grid gap-x-4 gap-y-1.5 sm:grid-cols-2'>
        {rules.map((rule) => (
          <li
            key={rule.id}
            className={cn(
              'flex items-center gap-2 transition-colors duration-150',
              rule.isMet && 'text-foreground'
            )}
          >
            <RuleMark isMet={rule.isMet} />
            {rule.label}
          </li>
        ))}
      </ul>
      <span aria-live='polite' className='sr-only'>
        {metCountLabel}
      </span>
    </FieldDescription>
  );
}

function inputTypeOf(isRevealed: boolean) {
  if (isRevealed) {
    return 'text';
  }
  return 'password';
}

function revealLabelOf(isRevealed: boolean) {
  if (isRevealed) {
    return 'Hide password';
  }
  return 'Show password';
}

type PasswordFieldProps = {
  label: string;
  value: string;
  autoComplete: 'new-password' | 'current-password';
  error: string | null;
  autoFocus?: boolean;
  inputRef?: React.Ref<HTMLInputElement>;
  readOnly?: boolean;
  onValueChange: (value: string) => void;
  children?: React.ReactNode;
};

/** The reveal button swaps its eye; the value never leaves the field's state. */
export function PasswordField({
  label,
  value,
  autoComplete,
  error,
  autoFocus,
  inputRef,
  readOnly,
  onValueChange,
  children,
}: PasswordFieldProps) {
  const [isRevealed, setIsRevealed] = useState(false);
  const shouldReduceMotion = usePrefersReducedMotion();
  const variants = swapVariantsOf(shouldReduceMotion);
  const hasError = Boolean(error);
  const inputType = inputTypeOf(isRevealed);
  const revealLabel = revealLabelOf(isRevealed);
  const glyphKey = String(isRevealed);

  function changeValue(event: React.ChangeEvent<HTMLInputElement>) {
    onValueChange(event.target.value);
  }

  function toggleReveal() {
    setIsRevealed((current) => !current);
  }

  return (
    <Field invalid={hasError} className='gap-0'>
      <FieldLabel className='mb-1.5'>{label}</FieldLabel>
      <div className='relative'>
        <Input
          ref={inputRef}
          type={inputType}
          value={value}
          autoComplete={autoComplete}
          autoCapitalize='none'
          autoCorrect='off'
          spellCheck={false}
          autoFocus={autoFocus}
          readOnly={readOnly}
          onChange={changeValue}
          className='pr-10'
        />
        <Button
          type='button'
          variant='ghost'
          size='icon-sm'
          aria-label={revealLabel}
          aria-pressed={isRevealed}
          onClick={toggleReveal}
          className='text-muted-foreground absolute top-1/2 right-0.5 -translate-y-1/2'
        >
          <AnimatePresence mode='popLayout' initial={false}>
            <motion.span
              key={glyphKey}
              variants={variants}
              initial='enter'
              animate='visible'
              exit='exit'
              transition={SWAP_TRANSITION}
              className='flex'
            >
              {isRevealed && <EyeOffIcon />}
              {!isRevealed && <EyeIcon />}
            </motion.span>
          </AnimatePresence>
        </Button>
      </div>
      <ErrorPresence error={error} />
      {children}
    </Field>
  );
}

'use client';

import {
  AnimatePresence,
  motion,
  type Transition,
  type Variants,
} from 'motion/react';
import { useEffect, useRef, useState } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { LoaderCircleIcon, type Icon } from '@/registry/ndeko/lib/icons';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Button } from '@/registry/ndeko/ui/button';
import { FieldError } from '@/registry/ndeko/ui/field';

export const PRODUCT_NAME = 'Tidewell';

const STEP_IN: Transition = { duration: 0.2, ease: [0.23, 1, 0.32, 1] };

const STEP_OUT: Transition = { duration: 0.15, ease: [0.23, 1, 0.32, 1] };

const SWAP_TRANSITION: Transition = { duration: 0.15, ease: [0.2, 0, 0, 1] };

const STEP_VARIANTS: Variants = {
  enter: { opacity: 0, scale: 0.98, filter: 'blur(2px)' },
  visible: { opacity: 1, scale: 1, filter: 'blur(0px)', transition: STEP_IN },
  exit: { opacity: 0, scale: 0.98, filter: 'blur(2px)', transition: STEP_OUT },
};

const SWAP_VARIANTS: Variants = {
  enter: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
  visible: { opacity: 1, scale: 1, filter: 'blur(0px)' },
  exit: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
};

const ERROR_VARIANTS: Variants = {
  enter: { height: 0, opacity: 0 },
  visible: { height: 'auto', opacity: 1, transition: STEP_IN },
  exit: { height: 0, opacity: 0, transition: STEP_OUT },
};

const FADE_VARIANTS: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1, transition: STEP_IN },
  exit: { opacity: 0, transition: STEP_OUT },
};

function stepVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return STEP_VARIANTS;
}

function swapVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return SWAP_VARIANTS;
}

function errorVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return ERROR_VARIANTS;
}

function BrandMark() {
  return (
    <svg viewBox='0 0 24 24' aria-hidden='true' className='size-6 shrink-0'>
      <rect width='24' height='24' rx='6' className='fill-primary' />
      <path
        d='M5 10q1.75-2.6 3.5 0t3.5 0 3.5 0 3.5 0'
        fill='none'
        stroke='white'
        strokeOpacity='0.7'
        strokeWidth='1.8'
        strokeLinecap='round'
      />
      <path
        d='M5 15.5q1.75-2.6 3.5 0t3.5 0 3.5 0 3.5 0'
        fill='none'
        stroke='white'
        strokeWidth='1.8'
        strokeLinecap='round'
      />
    </svg>
  );
}

type AuthFrameProps = {
  footer?: React.ReactNode;
  children: React.ReactNode;
};

/** A focused page: the window colour, the mark and its name, one card in the middle. */
export function AuthFrame({ footer, children }: AuthFrameProps) {
  return (
    <div className='bg-sidebar text-foreground flex min-h-dvh w-full flex-col'>
      <header className='flex h-14 shrink-0 items-center gap-2 px-4 sm:px-6'>
        <BrandMark />
        <span className='text-sm font-semibold'>{PRODUCT_NAME}</span>
      </header>
      <main className='flex flex-1 flex-col items-center px-4 pt-4 pb-16 sm:justify-center sm:pt-0'>
        <div className='flex w-full max-w-[25rem] flex-col gap-4'>
          <div className='bg-card hairline-ring ring-border dark:bg-foreground/[0.03] rounded-xl p-6 shadow-[0_1px_2px_rgb(0_0_0/0.04)] sm:p-7'>
            <AnimatedSize contentClassName='relative'>{children}</AnimatedSize>
          </div>
          {footer && (
            <p className='text-muted-foreground px-2 text-center text-xs text-balance'>
              {footer}
            </p>
          )}
        </div>
      </main>
    </div>
  );
}

type StepSwapProps = {
  stepKey: string;
  children: React.ReactNode;
};

/** The card resizes around it while one step gives way to the next. */
export function StepSwap({ stepKey, children }: StepSwapProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const variants = stepVariantsOf(shouldReduceMotion);

  return (
    <AnimatePresence mode='popLayout' initial={false}>
      <motion.div
        key={stepKey}
        variants={variants}
        initial='enter'
        animate='visible'
        exit='exit'
        className='flex flex-col gap-6'
      >
        {children}
      </motion.div>
    </AnimatePresence>
  );
}

type MarkTileProps = { icon: Icon };

export function MarkTile({ icon: TileIcon }: MarkTileProps) {
  return (
    <span className='keycap-3d text-muted-foreground flex size-10 items-center justify-center rounded-lg'>
      <TileIcon className='size-5' />
    </span>
  );
}

type CardHeadProps = {
  mark: React.ReactNode;
  title: string;
  /** Focuses the title when a step opens, so screen readers hear where they are. */
  autoFocusTitle?: boolean;
  children: React.ReactNode;
};

export function CardHead({
  mark,
  title,
  autoFocusTitle,
  children,
}: CardHeadProps) {
  const titleRef = useRef<HTMLHeadingElement>(null);

  useEffect(() => {
    if (autoFocusTitle) {
      titleRef.current?.focus();
    }
  }, [autoFocusTitle]);

  return (
    <div className='flex flex-col gap-4'>
      {mark}
      <div className='flex flex-col gap-1.5'>
        <h1
          ref={titleRef}
          tabIndex={-1}
          className='text-xl font-semibold text-balance outline-none'
        >
          {title}
        </h1>
        <p className='text-muted-foreground text-[13px] text-pretty'>
          {children}
        </p>
      </div>
    </div>
  );
}

type ErrorPresenceProps = {
  error: string | null;
};

/** Rendered inside a `Field`, so the error is tied to its control. It grows in and folds away. */
export function ErrorPresence({ error }: ErrorPresenceProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const variants = errorVariantsOf(shouldReduceMotion);

  return (
    <AnimatePresence initial={false}>
      {error && (
        <motion.div
          key='error'
          variants={variants}
          initial='enter'
          animate='visible'
          exit='exit'
          className='overflow-hidden'
        >
          <FieldError match className='pt-1.5'>
            {error}
          </FieldError>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

type SubmitButtonProps = {
  label: string;
  workingLabel: string;
  isWorking: boolean;
};

/** Becomes its working state in place: a spinner joins the label and the pill resizes to it. */
export function SubmitButton({
  label,
  workingLabel,
  isWorking,
}: SubmitButtonProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const variants = swapVariantsOf(shouldReduceMotion);
  const shownLabel = workingLabelOf(isWorking, label, workingLabel);

  return (
    <Button
      type='submit'
      size='lg'
      disabled={isWorking}
      focusableWhenDisabled
      className='w-full data-disabled:opacity-100 sm:w-auto'
    >
      <AnimatedSize
        as='span'
        axis='width'
        contentClassName='relative flex items-center gap-2'
      >
        <AnimatePresence mode='popLayout' initial={false}>
          {isWorking && (
            <motion.span
              key='spinner'
              variants={variants}
              initial='enter'
              animate='visible'
              exit='exit'
              transition={SWAP_TRANSITION}
              className='flex'
            >
              <LoaderCircleIcon className='animate-spin' />
            </motion.span>
          )}
        </AnimatePresence>
        <AnimatePresence mode='popLayout' initial={false}>
          <motion.span
            key={shownLabel}
            variants={variants}
            initial='enter'
            animate='visible'
            exit='exit'
            transition={SWAP_TRANSITION}
          >
            {shownLabel}
          </motion.span>
        </AnimatePresence>
      </AnimatedSize>
    </Button>
  );
}

function workingLabelOf(
  isWorking: boolean,
  label: string,
  workingLabel: string
) {
  if (isWorking) {
    return workingLabel;
  }
  return label;
}

type SwapLabelProps = { text: string };

export function SwapLabel({ text }: SwapLabelProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const variants = swapVariantsOf(shouldReduceMotion);

  return (
    <AnimatedSize as='span' axis='width' contentClassName='relative flex'>
      <AnimatePresence mode='popLayout' initial={false}>
        <motion.span
          key={text}
          variants={variants}
          initial='enter'
          animate='visible'
          exit='exit'
          transition={SWAP_TRANSITION}
          className='tabular-nums'
        >
          {text}
        </motion.span>
      </AnimatePresence>
    </AnimatedSize>
  );
}

/** Counts down once a second while it is above zero. */
export function useCountdown() {
  const [seconds, setSeconds] = useState(0);

  useEffect(() => {
    if (seconds <= 0) {
      return;
    }
    const timer = window.setTimeout(() => {
      setSeconds((current) => current - 1);
    }, 1000);
    return () => window.clearTimeout(timer);
  }, [seconds]);

  return { seconds, start: setSeconds };
}

export function clockOf(totalSeconds: number) {
  const rawMinutes = totalSeconds / 60;
  const minutes = Math.floor(rawMinutes);
  const seconds = totalSeconds % 60;
  const paddedSeconds = String(seconds).padStart(2, '0');
  return `${minutes}:${paddedSeconds}`;
}

